#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>
#include <format>

std::string resumen(const std::string& codigo, int unidades) {
    return std::format("pedido {{{0}}}: {1} unidades; copia={0}", codigo, unidades);
}

int main() {
    std::string codigo = "B";
    int cantidad = 4;
    std::string guardado = resumen(codigo, cantidad);
    cantidad = 9;
    std::cout << guardado << "\n" << resumen("", 0) << "\n" << resumen("{X}", 6);
    return 0;
}

